import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api, { authService } from '../services/api';

const Registro = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [tiposDocumento, setTiposDocumento] = useState([]);
  const [coordinadores, setCoordinadores] = useState([]);
  
  const [formData, setFormData] = useState({
    nombreUsuario: '',
    tipoIdentificacion: '',
    numeroIdentificacion: '',
    nombre: '',
    apellido: '',
    telefono: '',
    correoElectronico: '',
    coordinadorAsignado: '',
    password: '',
    confirmPassword: ''
  });

  // Cargar tipos de documento y coordinadores
  useEffect(() => {
    cargarDatosIniciales();
  }, []);

  const cargarDatosIniciales = async () => {
    try {
      const [tiposRes, coordinadoresRes] = await Promise.all([
        api.get('/tipos-documento'),
        api.get('/coordinadores')
      ]);

      setTiposDocumento(tiposRes.data.data || []);
      setCoordinadores(coordinadoresRes.data.data || []);
    } catch (error) {
      console.error('Error cargando datos:', error);
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      // Validaciones
      if (!formData.nombreUsuario) throw new Error('El nombre de usuario es obligatorio');
      if (!formData.tipoIdentificacion) throw new Error('Seleccione un tipo de identificación');
      if (!formData.numeroIdentificacion) throw new Error('El número de identificación es obligatorio');
      if (!formData.nombre) throw new Error('El nombre es obligatorio');
      if (!formData.apellido) throw new Error('El apellido es obligatorio');
      if (!formData.telefono) throw new Error('El teléfono es obligatorio');
      if (!formData.correoElectronico) throw new Error('El correo es obligatorio');
      if (!formData.coordinadorAsignado) throw new Error('Seleccione un coordinador');
      if (!formData.password) throw new Error('La contraseña es obligatoria');
      if (formData.password !== formData.confirmPassword) {
        throw new Error('Las contraseñas no coinciden');
      }
      if (formData.password.length < 6) {
        throw new Error('La contraseña debe tener al menos 6 caracteres');
      }

      // Validar email
      const emailRegex = /^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/;
      if (!emailRegex.test(formData.correoElectronico)) {
        throw new Error('Correo electrónico inválido');
      }

      // Crear objeto para enviar (sin confirmPassword)
      const { confirmPassword, ...datosEnvio } = formData;

      // Enviar al backend
      const response = await api.post('/auth/register', datosEnvio);
      
      setSuccess('✅ ¡Registro exitoso! Redirigiendo al login...');
      
      // Redirigir al login después de 2 segundos
      setTimeout(() => {
        navigate('/login');
      }, 2000);

    } catch (error) {
      console.error('Error:', error);
      if (error.response?.data?.message) {
        setError(error.response.data.message);
      } else {
        setError(error.message);
      }
    } finally {
      setLoading(false);
    }
  };

  const styles = {
    container: {
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      backgroundColor: '#f8fafc',
      fontFamily: "'Inter', sans-serif"
    },
    header: {
      backgroundColor: '#ffffff',
      borderBottom: '1px solid #e2e8f0',
      padding: '0 40px',
      height: '64px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      zIndex: 50,
      boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
    },
    logo: {
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    },
    logoImage: {
      width: '40px',
      height: '40px',
      objectFit: 'contain'
    },
    logoText: {
      fontSize: '24px',
      fontWeight: 600,
      color: '#091426'
    },
    main: {
      flexGrow: 1,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '80px 16px 32px 16px'
    },
    card: {
      width: '100%',
      maxWidth: '800px',
      backgroundColor: '#ffffff',
      borderRadius: '12px',
      border: '1px solid #c5c6cd',
      overflow: 'hidden',
      boxShadow: '0 1px 3px rgba(0,0,0,0.05), 0 1px 2px rgba(0,0,0,0.02)'
    },
    cardHeader: {
      padding: '32px 48px',
      textAlign: 'center',
      borderBottom: '1px solid #d3e4fe'
    },
    iconContainer: {
      display: 'flex',
      justifyContent: 'center',
      marginBottom: '24px'
    },
    iconBox: {
      width: '64px',
      height: '64px',
      backgroundColor: '#091426',
      borderRadius: '12px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'
    },
    iconBoxText: {
      color: 'white',
      fontSize: '32px',
      fontWeight: 'bold'
    },
    title: {
      fontSize: '32px',
      fontWeight: 600,
      color: '#091426',
      marginBottom: '8px'
    },
    subtitle: {
      fontSize: '16px',
      color: '#45474c'
    },
    form: {
      padding: '32px 48px'
    },
    section: {
      marginBottom: '40px'
    },
    sectionHeader: {
      display: 'flex',
      alignItems: 'center',
      gap: '12px',
      marginBottom: '24px'
    },
    sectionIcon: {
      fontSize: '24px',
      color: '#3c475a'
    },
    sectionTitle: {
      fontSize: '24px',
      fontWeight: 600,
      color: '#091426'
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: '1fr 1fr',
      gap: '24px'
    },
    fullWidth: {
      gridColumn: 'span 2'
    },
    formGroup: {
      display: 'flex',
      flexDirection: 'column',
      gap: '8px'
    },
    label: {
      fontSize: '14px',
      fontWeight: 500,
      color: '#0b1c30'
    },
    requiredStar: {
      color: '#ba1a1a'
    },
    input: {
      height: '44px',
      padding: '0 16px',
      borderRadius: '8px',
      border: '1px solid #c5c6cd',
      fontSize: '16px',
      backgroundColor: 'white',
      outline: 'none',
      transition: 'all 0.2s'
    },
    select: {
      height: '44px',
      padding: '0 16px',
      borderRadius: '8px',
      border: '1px solid #c5c6cd',
      fontSize: '16px',
      backgroundColor: 'white',
      outline: 'none',
      cursor: 'pointer'
    },
    errorAlert: {
      backgroundColor: '#ffdad6',
      color: '#93000a',
      padding: '12px 16px',
      borderRadius: '8px',
      marginBottom: '24px',
      display: 'flex',
      alignItems: 'center',
      gap: '12px'
    },
    successAlert: {
      backgroundColor: '#6cf8bb',
      color: '#005236',
      padding: '12px 16px',
      borderRadius: '8px',
      marginBottom: '24px',
      display: 'flex',
      alignItems: 'center',
      gap: '12px'
    },
    buttonGroup: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingTop: '24px',
      borderTop: '1px solid #d3e4fe',
      marginTop: '8px'
    },
    backButton: {
      background: 'none',
      border: 'none',
      color: '#45474c',
      fontSize: '14px',
      fontWeight: 500,
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    },
    submitButton: {
      backgroundColor: '#006c49',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      padding: '12px 40px',
      fontSize: '14px',
      fontWeight: 600,
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)',
      transition: 'all 0.2s'
    },
    footer: {
      backgroundColor: '#f8f9ff',
      padding: '32px 40px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: '16px',
      borderTop: '1px solid #c5c6cd'
    },
    footerText: {
      fontSize: '12px',
      fontWeight: 500,
      color: '#75777d'
    },
    footerLinks: {
      display: 'flex',
      gap: '24px'
    },
    footerLink: {
      fontSize: '12px',
      fontWeight: 500,
      color: '#75777d',
      textDecoration: 'none'
    },
    loadingSpinner: {
      animation: 'spin 1s linear infinite'
    }
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <header style={styles.header}>
        <div style={styles.logo}>
          <img src="/logosena.png" alt="SENA Logo" style={styles.logoImage} />
          <span style={styles.logoText}>Gestionytics</span>
        </div>
        <Link to="/login" style={{ color: '#45474c', textDecoration: 'none', fontSize: '16px' }}>
          Login
        </Link>
      </header>

      {/* Main Content */}
      <main style={styles.main}>
        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <div style={styles.iconContainer}>
              <div style={styles.iconBox}>
                <span style={styles.iconBoxText}>G</span>
              </div>
            </div>
            <h1 style={styles.title}>Crea tu cuenta</h1>
            <p style={styles.subtitle}>Únete a la plataforma de gestión de datos empresarial</p>
          </div>

          <form style={styles.form} onSubmit={handleSubmit}>
            {error && (
              <div style={styles.errorAlert}>
                <span>❌</span>
                <span>{error}</span>
              </div>
            )}
            {success && (
              <div style={styles.successAlert}>
                <span>✅</span>
                <span>{success}</span>
              </div>
            )}

            {/* Información de Cuenta */}
            <section style={styles.section}>
              <div style={styles.sectionHeader}>
                <span className="material-symbols-outlined" style={styles.sectionIcon}>lock_person</span>
                <h2 style={styles.sectionTitle}>Información de Cuenta</h2>
              </div>
              <div style={styles.grid}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nombre de Usuario <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="text"
                    name="nombreUsuario"
                    value={formData.nombreUsuario}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="ej. jdoe_admin"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Correo Electrónico <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="email"
                    name="correoElectronico"
                    value={formData.correoElectronico}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="correo@empresa.com"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Contraseña <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="password"
                    name="password"
                    value={formData.password}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="••••••••"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Confirmar Contraseña <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="password"
                    name="confirmPassword"
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="••••••••"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
              </div>
            </section>

            {/* Datos Personales */}
            <section style={styles.section}>
              <div style={styles.sectionHeader}>
                <span className="material-symbols-outlined" style={styles.sectionIcon}>badge</span>
                <h2 style={styles.sectionTitle}>Datos Personales</h2>
              </div>
              <div style={styles.grid}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Tipo de Identificación <span style={styles.requiredStar}>*</span></label>
                  <select
                    name="tipoIdentificacion"
                    value={formData.tipoIdentificacion}
                    onChange={handleChange}
                    style={styles.select}
                    required
                  >
                    <option value="">Seleccionar...</option>
                    {tiposDocumento.map(tipo => (
                      <option key={tipo._id} value={tipo._id}>
                        {tipo.nombre}
                      </option>
                    ))}
                  </select>
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Número de Identificación <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="text"
                    name="numeroIdentificacion"
                    value={formData.numeroIdentificacion}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="12345678"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nombres <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="text"
                    name="nombre"
                    value={formData.nombre}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="Juan Camilo"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Apellidos <span style={styles.requiredStar}>*</span></label>
                  <input
                    type="text"
                    name="apellido"
                    value={formData.apellido}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="Pérez Rodríguez"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Teléfono</label>
                  <input
                    type="tel"
                    name="telefono"
                    value={formData.telefono}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="+57 300 000 0000"
                    onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
                    onBlur={(e) => e.target.style.borderColor = '#c5c6cd'}
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Coordinador Asignado <span style={styles.requiredStar}>*</span></label>
                  <select
                    name="coordinadorAsignado"
                    value={formData.coordinadorAsignado}
                    onChange={handleChange}
                    style={styles.select}
                    required
                  >
                    <option value="">Seleccionar coordinador...</option>
                    {coordinadores.map(coord => (
                      <option key={coord._id} value={coord._id}>
                        {coord.nombre}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </section>

            {/* Form Actions */}
            <div style={styles.buttonGroup}>
              <button type="button" onClick={() => navigate('/login')} style={styles.backButton}>
                <span className="material-symbols-outlined">arrow_back</span>
                Volver al Login
              </button>
              <button type="submit" disabled={loading} style={{
                ...styles.submitButton,
                ...(loading ? { opacity: 0.7, cursor: 'not-allowed' } : {})
              }}>
                {loading ? (
                  <>
                    <span className="material-symbols-outlined" style={styles.loadingSpinner}>progress_activity</span>
                    Procesando...
                  </>
                ) : (
                  <>
                    Registrarse
                    <span className="material-symbols-outlined">how_to_reg</span>
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </main>

      {/* Footer */}
      <footer style={styles.footer}>
        <div style={styles.footerText}>
          © 2024 Gestionytics Enterprise Data Management. All rights reserved.
        </div>
        <div style={styles.footerLinks}>
          <a href="#" style={styles.footerLink}>Privacy Policy</a>
          <a href="#" style={styles.footerLink}>Terms of Service</a>
          <a href="#" style={styles.footerLink}>Support</a>
        </div>
      </footer>
    </div>
  );
};

export default Registro;
